import {cities,today,getWeather,weatherName,advice} from './weather.js';
const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cloud:'M6 18a4 4 0 0 1-1-7.9A6 6 0 0 1 17 8a5 5 0 0 1 1 10Z',umbrella:'M12 3v2M3 12a9 9 0 0 1 18 0H3m9 0v7a2 2 0 0 0 4 0',shirt:'m8 4-5 3 2 5 3-1v10h8V11l3 1 2-5-5-3c0 4-8 4-8 0Z',bag:'M5 8h14l1 13H4L5 8m4 0V5a3 3 0 0 1 6 0v3',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4l2-2m4 5h4',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',wind:'M3 8h12a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M5 16h4',bottle:'M10 2h4v4l2 3v12H8V9l2-3V2m-2 9h8m-8 6h8',check:'m5 12 4 4L19 6',refresh:'M20 7v5h-5M4 17v-5h5m-4-4a8 8 0 0 1 14-3l1 2M4 17l1 2a8 8 0 0 0 14-3'};
const icon=(n,cls='icon')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.cloud}"/></svg>`;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
let settings=read('cq-settings',{city:'上海',time:'08:00',pref:'normal',configured:false,paused:true});
if(!cities[settings.city]||!/^([01]\d|2[0-3]):[0-5]\d$/.test(settings.time)||!['cold','normal','hot'].includes(settings.pref))settings={city:'上海',time:'08:00',pref:'normal',configured:false,paused:true};
let weather=null,error='',loading=false,version=0,backend={ready:false},feedback=read('cq-feedback',{}),toastTimer;
const app=document.querySelector('#app');
const isSettings=()=>location.hash==='#settings';
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500)}
function persist(){localStorage.setItem('cq-settings',JSON.stringify(settings))}
function valid(){return weather&&weather.city===settings.city&&weather.daily.time[0]===today()&&!error}
function currentAdvice(){return valid()?advice(weather,settings.pref,settings.time):null}
function statusText(){return !backend.ready?'尚未接通每日推送':settings.paused?'提醒已暂停':backend.subscribed?'每日提醒已开启':'尚未订阅此设备'}
function render(){document.querySelector('#today-tab').classList.toggle('active',!isSettings());document.querySelector('#settings-tab').classList.toggle('active',isSettings());app.innerHTML=isSettings()?renderSettings():renderToday();bind()}
function renderToday(){const d=valid()?weather:null,a=currentAdvice();return `<div class="topline"><div><p class="eyebrow">${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'})} · 今日出门指南</p><h1>新的一天，<span>从容出发。</span></h1></div><a class="pill" href="#settings">${icon('pin')}${esc(settings.city)}⌄</a></div>${error?`<div class="error" role="alert">天气更新失败，暂时无法给出今天的建议。<button class="secondary" data-action="refresh">重新获取</button></div>`:''}<div class="grid"><div class="left"><section class="weather"><div class="weather-top"><span>${esc(settings.city)} · 今日天气</span><span class="tag">${d?'实时更新':loading?'正在更新':'等待天气'}</span></div><div class="weather-middle"><div><div class="temperature">${d?Math.round(d.current.temperature_2m):'—'}<sup>℃</sup></div><div class="weather-summary">${d?`${weatherName(d.current.weather_code)} &nbsp; ${Math.round(d.daily.temperature_2m_min[0])}° / ${Math.round(d.daily.temperature_2m_max[0])}° &nbsp; 体感 ${Math.round(d.current.apparent_temperature)}°`:'正在为今天的出门做准备'}</div></div>${icon(d&&d.current.weather_code===0?'sun':'cloud','weather-big')}</div><div class="weather-note">${icon('umbrella')}<span>${a?a.tip:loading?'正在获取今天的天气，请稍候…':'更新天气后，这里会告诉你出门注意什么。'}</span></div></section><section class="panel"><div class="section-head"><h2>${icon('shirt')}今天这样穿</h2><span class="tiny-tag">${{cold:'怕冷一点',normal:'正常体感',hot:'怕热一点'}[settings.pref]}</span></div>${a?`<div class="outfit"><div class="outfit-icon">${icon('shirt')}</div><div><h3>${a.outfit}</h3><p class="subtle">${a.detail}</p></div></div><div class="feedback"><span>今天穿得合适吗？</span>${[['less','穿少了'],['good','刚刚好'],['more','穿多了']].map(([key,label])=>`<button data-feedback="${key}" class="${feedback[today()]===key?'selected':''}" aria-pressed="${feedback[today()]===key}">${label}</button>`).join('')}</div>`:'<div class="empty"><p>拿到今天的天气后，为你推荐具体搭配。</p></div>'}</section><section class="panel"><div class="section-head"><h2>${icon('clock')}出门时段，心里有数</h2><span class="tiny-tag">北京时间</span></div>${d?renderHours(d):'<p class="subtle">天气更新后显示逐小时预报。</p>'}</section></div><aside class="right"><section class="panel"><h2>${icon('bag')}随身带上</h2>${a?`<div class="carry-list">${a.carry.map(i=>`<div class="carry-item"><span class="carry-icon">${icon(i.icon)}</span><div><h3>${i.title}</h3><p>${i.desc}</p></div></div>`).join('')}</div>`:'<p class="subtle">带伞、防晒还是防风？稍后为你整理。</p>'}</section><section class="panel notify"><h2>${icon('bell')}把提醒交给出门前</h2><div class="time">${settings.time}<span style="font-size:13px;font-weight:400;letter-spacing:0;margin-left:9px">每天 · 北京时间</span></div><p>${statusText()}。${backend.ready?'设置一次，每天出门前收到穿衣和随身建议。':'完成设置后，还需要接通后台通知服务。关闭网页后的自动提醒暂不可用。'}</p><a class="primary" href="#settings">${icon('bell')}${settings.configured?'管理每日提醒':'设置我的提醒'}</a><button class="text-link" style="border:0;background:none;width:100%" data-action="test">发送一条测试通知</button></section><div class="updated">${icon('refresh')}<span>${d?new Date(d.updated).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+' 更新':'尚未获取天气'}</span><button data-action="refresh">刷新</button></div></aside></div><p class="bottom-note">天气会变化，贴心的准备不会多余。</p>`}
function renderHours(d){const start=Math.min(Number(settings.time.split(':')[0]),18);return `<div class="hourly">${Array.from({length:6},(_,i)=>start+i).map(h=>`<div class="hour"><span>${String(h).padStart(2,'0')}:00</span>${icon(d.hourly.weather_code[h]===0?'sun':d.hourly.precipitation_probability[h]>=40?'umbrella':'cloud')}<b>${Number.isFinite(d.hourly.temperature_2m[h])?Math.round(d.hourly.temperature_2m[h])+'°':'—'}</b><span class="rain-value">${d.hourly.precipitation_probability[h]??'—'}% 降雨</span></div>`).join('')}</div>`}
function renderSettings(){const a=currentAdvice();return `<div class="topline"><div><p class="eyebrow">为你的日常，留一点贴心</p><h1>每天的提醒，<span>按你的习惯来。</span></h1></div></div><div class="settings-grid"><section class="panel"><h2>我的出门习惯</h2><form id="settings-form"><div class="form-row"><label for="city">所在城市</label><select name="city" id="city">${Object.keys(cities).map(c=>`<option ${c===settings.city?'selected':''}>${c}</option>`).join('')}</select><p class="subtle">手动选择城市，不需要获取你的位置。</p></div><div class="form-row"><label for="time">每天几点提醒你？</label><input type="time" name="time" id="time" value="${settings.time}" required><p class="subtle">建议设在出门前 15～30 分钟，按北京时间发送。</p></div><div class="form-row"><span class="label" id="pref-label">你的穿衣偏好</span><div class="preferences" role="group" aria-labelledby="pref-label">${[['cold','❄ 怕冷'],['normal','☀ 正常'],['hot','♨ 怕热']].map(([k,l])=>`<label><input type="radio" name="pref" value="${k}" ${k===settings.pref?'checked':''}><span>${l}</span></label>`).join('')}</div><p class="subtle">相同天气下，怕冷会推荐多穿一点，怕热则更轻薄。</p></div><button class="primary save" type="submit">${icon('check')}保存设置</button></form></section><div class="right"><section class="panel"><h2>${icon('bell')}每日通知</h2><div class="status-line"><span class="subtle">${settings.time} · 每天一条</span><span class="state">${statusText()}</span></div><p class="explain">${backend.ready?'允许系统通知并订阅此设备后，即可接收每日提醒。系统省电或网络状态可能影响送达。':'当前网站尚未接通后台推送服务，保存提醒时间不会自动开启每日通知。你可以先测试系统通知；测试成功也不代表定时推送已开启。'}</p><div class="setting-actions"><button class="primary" data-action="subscribe">开启每日通知</button><button class="secondary" data-action="test">发送测试通知</button>${backend.subscribed?`<button class="secondary" data-action="pause">${settings.paused?'恢复提醒':'暂停提醒'}</button>`:''}</div></section><section class="panel"><h2>你将收到这样的提醒</h2><p class="subtle">重要信息，直接写在通知里。</p><div class="notification-preview"><small>↗ 出门前 <span style="float:right">${settings.time}</span></small><strong>早上好，今天出门这样准备：</strong>${a?esc(a.body):'天气更新成功后，这里会展示你的真实提醒内容。'}</div><p class="explain">通知内容会在发送前获取当天预报。获取失败时明确提醒更新失败，不沿用旧天气。</p></section></div></div>`}
async function refresh(){const ticket=++version;loading=true;error='';weather=null;render();try{const result=await getWeather(settings.city);if(ticket===version)weather=result}catch(e){if(ticket===version)error=e.message}finally{if(ticket===version){loading=false;render()}}}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>({refresh, test:testNotification,subscribe:subscribe,pause:pause}[b.dataset.action])());document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{feedback[today()]=b.dataset.feedback;try{localStorage.setItem('cq-feedback',JSON.stringify(Object.fromEntries(Object.entries(feedback).slice(-90))));toast('已记录今天的感受，暂不自动改变穿衣偏好。');render()}catch{toast('无法保存反馈，请检查浏览器存储设置。')}});document.querySelector('#settings-form')?.addEventListener('submit',saveSettings)}
async function saveSettings(e){e.preventDefault();const form=new FormData(e.target);const next={...settings,city:form.get('city'),time:form.get('time'),pref:form.get('pref'),configured:true};if(!cities[next.city]||!/^([01]\d|2[0-3]):[0-5]\d$/.test(next.time)||!['cold','normal','hot'].includes(next.pref))return toast('请检查城市和提醒时间。');try{if(backend.subscribed)await api('/api/settings',next);settings=next;persist();toast('已保存你的出门习惯。');await refresh()}catch{toast('设置未能保存，请重试。')}}
async function api(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(read('cq-device',null)||'')},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error('通知服务暂时不可用');return r.json()}
async function registration(){if(!('serviceWorker'in navigator)||!('Notification'in window))throw Error('当前浏览器不支持系统通知。请使用支持通知的浏览器；iPhone 需要先添加到主屏幕。');return navigator.serviceWorker.register('./sw.js')}
async function testNotification(){try{if(!valid())return toast('请先获取今天的天气，再发送测试通知。');if(!('Notification'in window))throw Error('当前浏览器不支持系统通知。');const granted=await Notification.requestPermission();if(granted!=='granted')throw Error('通知权限未开启，请在浏览器的网站设置中允许通知。');await registration();const reg=await navigator.serviceWorker.ready;await reg.showNotification('出门前 · 测试通知',{body:currentAdvice().body,icon:'favicon.svg',tag:'chumen-test',data:{url:'./'}});toast('已请求显示测试通知，请检查系统通知栏。')}catch(e){toast(e.message)}}
async function subscribe(){if(!backend.ready)return toast('每日推送尚未接通，当前不能开启。提醒时间已保留在此设备。');try{if(!settings.configured)return toast('请先保存城市、时间和穿衣偏好。');if(!('PushManager'in window)||!('Notification'in window))throw Error('此浏览器不支持后台通知。');if(await Notification.requestPermission()!=='granted')throw Error('请先允许系统通知。');await registration();const reg=await navigator.serviceWorker.ready;const key=Uint8Array.from(atob(backend.publicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const subscription=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const result=await api('/api/subscribe',{subscription:subscription.toJSON(),settings:{...settings,paused:false}});localStorage.setItem('cq-device',JSON.stringify(result.token));backend.subscribed=true;settings.paused=false;persist();render();toast('每日通知已开启。')}catch(e){toast(e.message)}}
async function pause(){try{const next={...settings,paused:!settings.paused};await api('/api/settings',next);settings=next;persist();render();toast(settings.paused?'已暂停每日提醒。':'已恢复每日提醒。')}catch(e){toast(e.message)}}
async function initBackend(){try{backend=await api('/api/status');if(backend.subscribed){settings={...settings,...backend.settings};persist()}}catch{backend={ready:false}}render()}
window.addEventListener('hashchange',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&(!valid()||Date.now()-weather.updated>1800000))refresh()});setInterval(()=>{if(weather&&weather.daily.time[0]!==today())refresh()},60000);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_departure_advice',description:'读取所选城市今天的真实天气与出门建议，不修改设置。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async(input)=>{if(!input||Object.keys(input).length)throw Error('不接受参数');if(!valid())throw Error('天气尚未更新成功');return {city:settings.city,date:today(),...currentAdvice()}}})}catch{}}
render();initBackend().then(refresh);
